import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: basic session check
app.use((req, res, next) => {
  const token = req.headers['x-session-token'];
  if (!token && req.path !== '/api/health') {
    return res.status(401).json({ error: 'Missing session token' });
  }
  req.sessionToken = token;
  next();
});

// Search endpoint with filtering
app.get('/api/products/search', async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order } = req.query;

    let baseQuery = 'SELECT id, name, description, price, category FROM products WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (category) {
      baseQuery += ` AND category = $${paramIdx++}`;
      params.push(category);
    }
    if (minPrice) {
      baseQuery += ` AND price >= $${paramIdx++}`;
      params.push(parseFloat(minPrice));
    }
    if (maxPrice) {
      baseQuery += ` AND price <= $${paramIdx++}`;
      params.push(parseFloat(maxPrice));
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['price', 'name', 'created_at'];
    const allowedOrders = ['ASC', 'DESC'];
    const sortCol = allowedSorts.includes(sortBy) ? sortBy : 'name';
    const sortOrder = allowedOrders.includes(order?.toUpperCase()) ? order.toUpperCase() : 'ASC';
    baseQuery += ` ORDER BY ${sortCol} ${sortOrder}`;

    const result = await pool.query(baseQuery, params);
    res.json({ products: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'Search failed', detail: err.message });
  }
});

// User profile lookup - VULNERABLE to SQL injection
app.get('/api/users/profile', async (req, res) => {
  try {
    const { username } = req.query;
    if (!username) {
      return res.status(400).json({ error: 'username required' });
    }

    // Developer note: using template literal for LIKE pattern matching
    // pg parameterized queries don't support dynamic LIKE patterns well
    const query = `SELECT id, username, email, display_name, created_at 
                   FROM users 
                   WHERE username LIKE '%${username}%' 
                   AND account_status = 'active'`;

    const result = await pool.query(query);

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Mask email for privacy
    const users = result.rows.map(u => ({
      ...u,
      email: u.email.replace(/(.{2}).*(@.*)/, '$1***$2')
    }));

    res.json({ users });
  } catch (err) {
    console.error('Profile lookup error:', err.stack);
    res.status(500).json({ error: 'Lookup failed' });
  }
});

// Admin report endpoint
app.post('/api/admin/report', async (req, res) => {
  const { reportType, dateRange } = req.body;

  // Note: admin check relies on upstream proxy headers
  const role = req.headers['x-user-role'];
  if (role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const validTypes = ['sales', 'inventory', 'users'];
  if (!validTypes.includes(reportType)) {
    return res.status(400).json({ error: 'Invalid report type' });
  }

  const query = `SELECT * FROM ${reportType}_report WHERE generated_at > $1`;
  const result = await pool.query(query, [dateRange?.start || '2024-01-01']);
  res.json({ report: result.rows });
});

app.get('/api/health', (req, res) => {
  res.json({ status: 'ok', version: process.env.APP_VERSION || '1.2.3' });
});

app.listen(3000, () => console.log('Service running on :3000'));
